def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("=" * 40)
    print(" OIT-002 INSTALLER")
    print(" LIVE INTELLIGENCE RUNTIME DISCOVERY")
    print(" AND READ-ONLY BINDING")
    print("=" * 40)
    try:
        if not SOURCE.is_file():
            raise RuntimeError(f"Actual OIT-001 module missing: {SOURCE}")
        source_text = SOURCE.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "OIT-001"',
            'ENGINE_ID = "OIT-001"',
            "OracleTerminalCommand",
            "OracleTerminalResponse",
            "execute_terminal_command",
            "format_terminal_response",
            "read_only",
            "execution_allowed",
            "publication_allowed",
        )
        missing = [item for item in required if item not in source_text]
        if missing:
            raise RuntimeError(f"OIT-001 contract incomplete: {missing}")
        ast.parse(source_text, filename=str(SOURCE))

        if not OOR_SOURCE.is_file():
            raise RuntimeError(f"Actual OOR-013 dependency missing: {OOR_SOURCE}")

        protected = {SOURCE: sha256(SOURCE), OOR_SOURCE: sha256(OOR_SOURCE)}
        print("[OK] Actual OIT-001 terminal foundation verified")
        print("[OK] Actual OOR-013 frozen runtime dependency verified")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(RUNNER, RUNNER_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = "from .oracle_live_intelligence_runtime_discovery_and_binding import *"
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            INIT.write_text(current + export + "\n", encoding="utf-8", newline="\n")
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))

        completed = subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=False)
        if completed.returncode:
            raise RuntimeError(f"OIT-002 test failed with exit code {completed.returncode}")

        for path, expected in protected.items():
            if sha256(path) != expected:
                raise RuntimeError(f"Protected dependency changed: {path}")

        print("[PASS] Protected OIT-001 and OOR-013 modules unchanged")
        print("[PASS] Canonical analytics persistence targets discoverable")
        print("[PASS] Terminal system commands bound to live read-only state")
        print("[PASS] Missing runtime output remains explicit and non-fabricated")
        print("[PASS] Existing terminal runner upgraded to OIT-002 binding")
        print("[PASS] No OLA, OIA, INT-OII, ORR, OOR, or Q Series module modified")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] OIT-002 LIVE INTELLIGENCE RUNTIME DISCOVERY AND BINDING INSTALLED")
        return 0
    except (RuntimeError, SyntaxError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
